import sys

def solve():
    input_data = sys.stdin.read().splitlines()
    if not input_data:
        return

    try:
        n = int(input_data[0].strip())
    except ValueError:
        return

    fragments = []
    for i in range(1, n + 1):
        fragments.append(input_data[i].strip())

    # Precompute overlaps
    # overlap[i][j] = length of overlap if fragment i precedes fragment j, or -1 if no overlap
    # Overlap condition: suffix of i matches prefix of j with length >= 5
    overlap = [[-1] * n for _ in range(n)]

    for i in range(n):
        for j in range(n):
            if i == j:
                continue
            s1 = fragments[i]
            s2 = fragments[j]
            max_len = min(len(s1), len(s2))
            found = -1
            for l in range(5, max_len + 1):
                if s1.endswith(s2[:l]):
                    found = l
            if found != -1:
                overlap[i][j] = found

    # Build adjacency list for the graph
    # Since overlaps are unique, each node has at most one outgoing edge
    adj = [[] for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if overlap[i][j] != -1:
                adj[i].append(j)

    # Check for cycles and find longest path
    # Since the problem guarantees no cycles, we can use memoization
    memo = {}
    path_len = {}
    parent = {}

    def get_longest_path(u):
        if u in memo:
            return memo[u]

        if not adj[u]:
            memo[u] = 1
            path_len[u] = 1
            parent[u] = -1
            return 1

        max_l = 0
        best_v = -1
        for v in adj[u]:
            l = 1 + get_longest_path(v)
            if l > max_l:
                max_l = l
                best_v = v

        memo[u] = max_l
        path_len[u] = max_l
        parent[u] = best_v
        return max_l

    # Calculate longest path starting from each node
    max_global_len = 0
    start_nodes = []

    for i in range(n):
        l = get_longest_path(i)
        if l > max_global_len:
            max_global_len = l
            start_nodes = [i]
        elif l == max_global_len:
            start_nodes.append(i)

    # If there are multiple start nodes with the same max length, it's ambiguous
    if len(start_nodes) > 1:
        print("AMBIGUOUS")
        return

    # Reconstruct the path
    start_node = start_nodes[0]
    path = []
    curr = start_node
    while curr != -1:
        path.append(curr)
        curr = parent[curr]

    path.reverse()

    # Construct the result string
    if not path:
        print("")
        return

    result = fragments[path[0]]
    for i in range(1, len(path)):
        prev_idx = path[i-1]
        curr_idx = path[i]
        ov = overlap[prev_idx][curr_idx]
        # Remove the overlapping prefix from the current fragment
        # The overlap is the suffix of prev and prefix of curr
        # We need to remove the first 'ov' characters of curr
        result += fragments[curr_idx][ov:]

    print(result)

if __name__ == "__main__":
    solve()
